// The app's logic without Android: the generated hub client, the
// connection, and what the screens show, worked out from snapshots. Its
// tests run on the JVM, in CI, with no device.
plugins {
    alias(libs.plugins.kotlin.jvm)
}

kotlin {
    jvmToolchain(21)
    explicitApi()
}

sourceSets {
    main {
        // Generated by `make proto` (buf.gen.yaml); committed.
        java.srcDir("src/main/gen")
        kotlin.srcDir("src/main/gen")
    }
}

// The generated code isn't ours to make explicit.
tasks.named<org.jetbrains.kotlin.gradle.tasks.KotlinCompile>("compileKotlin") {
    compilerOptions.freeCompilerArgs.add("-Xexplicit-api=warning")
}

dependencies {
    api(libs.protobuf.kotlin.lite)
    api(libs.coroutines.core)
    implementation(libs.connect.okhttp)
    implementation(libs.connect.javalite)
    implementation(libs.okhttp)

    testImplementation(libs.junit)
    testImplementation(libs.coroutines.test)
    testImplementation(libs.okhttp.mockwebserver)
}
